(3439613, 480236, 61679, '<td valign="top">Back to comment: One of two 10''s I gave in this challenge.  Exceptional post processing.  Congratulations on a great image.</td>', 'Back to comment: One of two 10''s I gave in this challenge.  Exceptional post processing.  Congratulations on a great image.', '2007-03-07 17:24:38.000000', NULL, 1),
(3439615, 477771, 61679, '<td valign="top">Back to comment: One of two 10''s I gave in this challenge.  Never thought I would say that about a stop sign.  Wonderful perspective, realistic looking colors, great composition.  Nice job!</td>', 'Back to comment: One of two 10''s I gave in this challenge.  Never thought I would say that about a stop sign.  Wonderful perspective, realistic looking colors, great composition.  Nice job!', '2007-03-07 17:25:45.000000', NULL, 1),
(3439620, 479559, 61679, '<td valign="top">Back to comment:  Exceptional panning technique and timing.  Great looking colors and sharpness.  Put you in my top five for the challenge.</td>', 'Back to comment:  Exceptional panning technique and timing.  Great looking colors and sharpness.  Put you in my top five for the challenge.', '2007-03-07 17:27:22.000000', NULL, 1),
(3439621, 478202, 61679, '<td valign="top">Back to comment:  Exceptional composition and sharpness.  Great looking colors.  Put you in my top five for the challenge.</td>', 'Back to comment:  Exceptional composition and sharpness.  Great looking colors.  Put you in my top five for the challenge.', '2007-03-07 17:27:52.000000', NULL, 1),
(3439622, 479397, 66515, '<td valign="top">Interesting composition. I like the lines of the leaves. They take your eye around the picture nicely. The central group of blossoms anchors the shot nicely and creates nice foreground interest. <br/> <br/>The shot could be a bit sharper. If a tripod wasn''t used I''d recommend one. The colors seem a little bit oversaturated. <br/> <br/>This certainly meets the challenge. Perhaps not the most creative idea but its fresh enough to work.</td>', 'Interesting composition. I like the lines of the leaves. They take your eye around the picture nicely. The central group of blossoms anchors the shot nicely and creates nice foreground interest.  The shot could be a bit sharper. If a tripod wasn''t used I''d recommend one. The colors seem a little bit oversaturated.  This certainly meets the challenge. Perhaps not the most creative idea but its fresh enough to work.', '2007-03-07 17:28:12.000000', NULL, 1),
(3439628, 480258, 23016, '<td valign="top">In my opinion a closer aperture get a better results. In this photo there are not enough details, a small deep of field, only the nose and the eye are on focus.<br/>Is it a rubber frog?</td>', 'In my opinion a closer aperture get a better results. In this photo there are not enough details, a small deep of field, only the nose and the eye are on focus.Is it a rubber frog?', '2007-03-07 17:30:08.000000', NULL, 1),
