(3440623, 479582, 63218, '<td valign="top">not interesting (to me)</td>', 'not interesting (to me)', '2007-03-07 21:05:18.000000', NULL, 1),
(3440630, 479080, 61651, '<td valign="top">Very clever - made me laugh, and made me see such an ordinary object in a whole new light.</td>', 'Very clever - made me laugh, and made me see such an ordinary object in a whole new light.', '2007-03-07 21:06:41.000000', NULL, 1),
(3440650, 479963, 58452, '<td valign="top">Nice colors and shapes.  I could do without the sun and flare.</td>', 'Nice colors and shapes.  I could do without the sun and flare.', '2007-03-07 21:12:26.000000', NULL, 1),
(3440652, 478303, 58452, '<td valign="top">Nice portrait.  Unique pose.</td>', 'Nice portrait.  Unique pose.', '2007-03-07 21:14:35.000000', NULL, 1),
(3440653, 479952, 70375, '<td valign="top">Okay, I''ll give you that setting fire to a strawberry is an interesting idea. :)  This would have caught my eye a lot better if there were no wall there though... just the black countertop, the white plate, the strawberry, and the fire... I realize that it is hard to get a camera above a fire as that is where the heat goes... perhaps a black matboard would have helped out a little here? There appears to be quite a bit of grain (noise in the black areas of the photograph), ISO might be set a bit high? It did make me smile though and the strawberry looks good enough to eat :) No voting BTW, just commenting :)</td>', 'Okay, I''ll give you that setting fire to a strawberry is an interesting idea. :)  This would have caught my eye a lot better if there were no wall there though... just the black countertop, the white plate, the strawberry, and the fire... I realize that it is hard to get a camera above a fire as that is where the heat goes... perhaps a black matboard would have helped out a little here? There appears to be quite a bit of grain (noise in the black areas of the photograph), ISO might be set a bit high? It did make me smile though and the strawberry looks good enough to eat :) No voting BTW, just commenting :)', '2007-03-07 21:15:15.000000', NULL, 1),
(3440663, 479436, 70375, '<td valign="top">FABULOUS!! Very red :) I love the red carpet and the red ribbon. Kudos on a fabulous idea and execution! The only thing I could see that might make this a bit more on the grabby side is a deeper depth of field so that every curl of the ribbon were in focus. I see this doing well :) Good Luck! NVJC.</td>', 'FABULOUS!! Very red :) I love the red carpet and the red ribbon. Kudos on a fabulous idea and execution! The only thing I could see that might make this a bit more on the grabby side is a deeper depth of field so that every curl of the ribbon were in focus. I see this doing well :) Good Luck! NVJC.', '2007-03-07 21:17:52.000000', NULL, 1),
(3440665, 479968, 58452, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2007-03-07 21:18:48.000000', NULL, 1),
(3440668, 480273, 70375, '<td valign="top">Wow! How pretty! Where did you find cherries in the middle of the winter? :) This is a great shot and a very nice take on RED. Processing is really nicely done too. Not much more I can say except good luck and good work! NVJC.</td>', 'Wow! How pretty! Where did you find cherries in the middle of the winter? :) This is a great shot and a very nice take on RED. Processing is really nicely done too. Not much more I can say except good luck and good work! NVJC.', '2007-03-07 21:19:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3440671, 480254, 73875, '<td valign="top">not very original</td>', 'not very original', '2007-03-07 21:21:01.000000', NULL, 1),
(3440675, 478630, 70375, '<td valign="top">A fire hydrant dressed to impress :) Red and green are natural complimentary colours and you have made good use of them in this photograph. The only thing I can think of to suggest is maybe moving the twig at the bottom of the pic and setting up a matboard behind the hydrant to block out the tree and bush. Other than that, I have only to say good luck! Very creative shot! NVJC.</td>', 'A fire hydrant dressed to impress :) Red and green are natural complimentary colours and you have made good use of them in this photograph. The only thing I can think of to suggest is maybe moving the twig at the bottom of the pic and setting up a matboard behind the hydrant to block out the tree and bush. Other than that, I have only to say good luck! Very creative shot! NVJC.', '2007-03-07 21:22:37.000000', NULL, 1),
(3440677, 479870, 75129, '<td valign="top">Wow, really creative. I saw a few other card themes, but this one is the best. Very interesting.</td>', 'Wow, really creative. I saw a few other card themes, but this one is the best. Very interesting.', '2007-03-07 21:22:58.000000', NULL, 1),
(3440689, 480331, 70375, '<td valign="top">I like that the focus in this pic falls to the 6''s on the front rather than the 5,4,3 on the top :) Interesting idea. I hope to see this photo do well. As far as improvements go, I would only suggest a bit of pop for the red colour itself. It is a bit dull here. Good luck and excellent execution of a great idea! NVJC.</td>', 'I like that the focus in this pic falls to the 6''s on the front rather than the 5,4,3 on the top :) Interesting idea. I hope to see this photo do well. As far as improvements go, I would only suggest a bit of pop for the red colour itself. It is a bit dull here. Good luck and excellent execution of a great idea! NVJC.', '2007-03-07 21:26:36.000000', NULL, 1),
(3440708, 479384, 75023, '<td valign="top">I like the pic but think the sign and red spot in the water where distracting. I think you would have had stronger image if they either tied into the story or were left out.</td>', 'I like the pic but think the sign and red spot in the water where distracting. I think you would have had stronger image if they either tied into the story or were left out.', '2007-03-07 21:34:16.000000', NULL, 1),
(3440739, 479986, 70375, '<td valign="top">Let me start off by saying this is a great concept and very unique. Pic is a bit busy but I do like that the only red item is the numbers that are putting the person in "the RED". To suggest an improvement, I would say, move the pen, move the coffee cup, and open the appointment book :) It is a nice, crisp photo though and if it were just about clarity, I would say top marks ;) Good Luck! NVJC.</td>', 'Let me start off by saying this is a great concept and very unique. Pic is a bit busy but I do like that the only red item is the numbers that are putting the person in "the RED". To suggest an improvement, I would say, move the pen, move the coffee cup, and open the appointment book :) It is a nice, crisp photo though and if it were just about clarity, I would say top marks ;) Good Luck! NVJC.', '2007-03-07 21:49:03.000000', NULL, 1),
(3440745, 480525, 74496, '<td valign="top">Great composition!  It is too bad the bottom looks a little blurry  (7)</td>', 'Great composition!  It is too bad the bottom looks a little blurry  (7)', '2007-03-07 21:51:11.000000', NULL, 1),
(3440748, 480150, 63218, '<td valign="top">I''m hoping you put some notes in, I''m curious how this wass done!</td>', 'I''m hoping you put some notes in, I''m curious how this wass done!', '2007-03-07 21:52:00.000000', NULL, 1),
(3440752, 480159, 74496, '<td valign="top">What a picture!!  Love the composition.  Focus is right on!</td>', 'What a picture!!  Love the composition.  Focus is right on!', '2007-03-07 21:53:37.000000', NULL, 1),
(3440755, 480202, 74496, '<td valign="top">The red tablecloth is coming out too strong, and the berries are not in focus</td>', 'The red tablecloth is coming out too strong, and the berries are not in focus', '2007-03-07 21:54:03.000000', NULL, 1),
(3440756, 477796, 70514, '<td valign="top">Such sweet hands.</td>', 'Such sweet hands.', '2007-03-07 21:54:26.000000', NULL, 1),
