(3440851, 479208, 70375, '<td valign="top">Me likey! LOL Seriously though, I do like the shot. Reds are great and not overpowering. The only suggestion I have is to put the strawberry into focus instead of the teeth :) (those are some nice white teeth BTW) Great idea and good execution. GOOD LUCK :) NVJC.</td>', 'Me likey! LOL Seriously though, I do like the shot. Reds are great and not overpowering. The only suggestion I have is to put the strawberry into focus instead of the teeth :) (those are some nice white teeth BTW) Great idea and good execution. GOOD LUCK :) NVJC.', '2007-03-07 22:10:52.000000', NULL, 1),
(3440854, 479694, 68751, '<td valign="top">I feel this could of had a bit more grass at the bottom but beautiful picture!</td>', 'I feel this could of had a bit more grass at the bottom but beautiful picture!', '2007-03-07 22:11:06.000000', NULL, 1),
(3440859, 480088, 51623, '<td valign="top">the flowers are beautiful...however the eyes of the bride in the background look a little odd and distracting.</td>', 'the flowers are beautiful...however the eyes of the bride in the background look a little odd and distracting.', '2007-03-07 22:11:30.000000', NULL, 1),
