(3441289, 478815, 58452, '<td valign="top">Good balance between the rock with the bouy and the breaking wave.  Might look nicer with some late evening or morning light.</td>', 'Good balance between the rock with the bouy and the breaking wave.  Might look nicer with some late evening or morning light.', '2007-03-07 23:36:36.000000', NULL, 1),
(3441301, 480533, 58452, '<td valign="top">Nice textures, shapes, and shades of gray in the icicle.  The repeating &gt;&gt;&gt;s are really nice.  This works well against a black background.</td>', 'Nice textures, shapes, and shades of gray in the icicle.  The repeating >>>s are really nice.  This works well against a black background.', '2007-03-07 23:39:00.000000', NULL, 1),
(3441307, 480163, 58452, '<td valign="top">Good composition.  I wonder if a close-up of the head would have more "red" effect?</td>', 'Good composition.  I wonder if a close-up of the head would have more "red" effect?', '2007-03-07 23:40:16.000000', NULL, 1),
(3441308, 480192, 58452, '<td valign="top">Nice textures and good composition.</td>', 'Nice textures and good composition.', '2007-03-07 23:40:45.000000', NULL, 1),
