(3443250, 477472, 49668, '<td valign="top">hopefully this is more of a joke.. not much thought went into it obviously</td>', 'hopefully this is more of a joke.. not much thought went into it obviously', '2007-03-08 13:07:46.000000', NULL, 1),
(3443257, 479055, 69102, '<td valign="top">what an odd effect. the trees in the upper background look like they are falling forward on the house, like a wave. the textures here are interesting, but wish the landscape wasn''t quite so compressed and that the tree branches in the front were not obscuring the house.</td>', 'what an odd effect. the trees in the upper background look like they are falling forward on the house, like a wave. the textures here are interesting, but wish the landscape wasn''t quite so compressed and that the tree branches in the front were not obscuring the house.', '2007-03-08 13:10:16.000000', NULL, 1),
(3443262, 480525, 69102, '<td valign="top">the reflections don''t work for me. perhaps you were going for the idea of the bird missing the sky, but I think you would have needed to get closer or for that to translate effectively.</td>', 'the reflections don''t work for me. perhaps you were going for the idea of the bird missing the sky, but I think you would have needed to get closer or for that to translate effectively.', '2007-03-08 13:11:10.000000', NULL, 1),
