(3443337, 479679, 69102, '<td valign="top">best one of these by far. very well done. composition with the single star is spot on.</td>', 'best one of these by far. very well done. composition with the single star is spot on.', '2007-03-08 13:29:19.000000', NULL, 1),
(3443344, 480508, 42100, '<td valign="top">Great color and clarity, good composition as well.  I like the use of shallow DOF, but find the transitions of focus abrupt and uncomfortable, especially in the foreground.  Very nice overall though!</td>', 'Great color and clarity, good composition as well.  I like the use of shallow DOF, but find the transitions of focus abrupt and uncomfortable, especially in the foreground.  Very nice overall though!', '2007-03-08 13:31:04.000000', NULL, 1),
(3443352, 479080, 69102, '<td valign="top">colors are really muddy and unappealing.</td>', 'colors are really muddy and unappealing.', '2007-03-08 13:33:31.000000', NULL, 1),
(3443357, 479624, 42100, '<td valign="top">I really like the composition and very bold color combo.  There does seem to be detail missing from the exterior of the tulip petals that should be there.  But I still like how graphic this is in style...nicely done!</td>', 'I really like the composition and very bold color combo.  There does seem to be detail missing from the exterior of the tulip petals that should be there.  But I still like how graphic this is in style...nicely done!', '2007-03-08 13:35:42.000000', NULL, 1),
