(3445497, 478473, 67301, '<td valign="top">love this idea and the shot is very clear. my only resevation is the stark white background, it seems to refect off the side of green prpper.But I am being picky = 10</td>', 'love this idea and the shot is very clear. my only resevation is the stark white background, it seems to refect off the side of green prpper.But I am being picky = 10', '2007-03-09 05:50:45.000000', NULL, 1),
(3445510, 480159, 67301, '<td valign="top">This is a fantastic shot and IMO is the best.The clarity within the landscape is awesome even down to the rocks below the water it is big WOW factor for me. Yet the life saver floatation ring jumps out and the challenge is met. A small but very poignant object. If I could I would score this shot at 15 So Good luck 10</td>', 'This is a fantastic shot and IMO is the best.The clarity within the landscape is awesome even down to the rocks below the water it is big WOW factor for me. Yet the life saver floatation ring jumps out and the challenge is met. A small but very poignant object. If I could I would score this shot at 15 So Good luck 10', '2007-03-09 06:00:14.000000', NULL, 1),
(3445513, 480214, 67301, '<td valign="top">beautiful shot with great expression and clarity of the face=9</td>', 'beautiful shot with great expression and clarity of the face=9', '2007-03-09 06:01:18.000000', NULL, 1),
