(3446085, 480403, 41116, '<td valign="top">Great imagination! I like the focus on the inside of the pepper, and the faint trace of what looks like a flame in the corner of the right eye. - 8</td>', 'Great imagination! I like the focus on the inside of the pepper, and the faint trace of what looks like a flame in the corner of the right eye. - 8', '2007-03-09 11:22:38.000000', NULL, 1),
(3446091, 480170, 58610, '<td valign="top">I think your background, though intended to enhance the "redness", I''m sure, really detracts from the overall composition. YOu might try shooting the red bow  on a different background (solid black, for instance) and see how you like it.</td>', 'I think your background, though intended to enhance the "redness", I''m sure, really detracts from the overall composition. YOu might try shooting the red bow  on a different background (solid black, for instance) and see how you like it.', '2007-03-09 11:24:24.000000', NULL, 1),
(3446094, 479522, 41116, '<td valign="top">Stunning photo! I like the blur on the wings, shows the motion of the moment. - 9</td>', 'Stunning photo! I like the blur on the wings, shows the motion of the moment. - 9', '2007-03-09 11:24:52.000000', NULL, 1),
(3446095, 479001, 68504, '<td valign="top">Reflections on shimmering sand and shallow waves could be a study in itself.  Wish the leading lines to upper 2/3 right were a little more emphasized.</td>', 'Reflections on shimmering sand and shallow waves could be a study in itself.  Wish the leading lines to upper 2/3 right were a little more emphasized.', '2007-03-09 11:25:07.000000', NULL, 1),
(3446100, 479681, 58610, '<td valign="top">Very clever shot. I''m wishing for a little greater dof so that the focus goes from the front edge of the chocolat to the back edge of the strawberry. Nicely exposed and composed.</td>', 'Very clever shot. I''m wishing for a little greater dof so that the focus goes from the front edge of the chocolat to the back edge of the strawberry. Nicely exposed and composed.', '2007-03-09 11:25:56.000000', NULL, 1),
(3446103, 479888, 41116, '<td valign="top">Nice emphasis on the red drink. I like how the lemon draws attention to the drink. - 7</td>', 'Nice emphasis on the red drink. I like how the lemon draws attention to the drink. - 7', '2007-03-09 11:26:33.000000', NULL, 1),
(3446111, 479901, 58610, '<td valign="top">Interesting idea. My eye is confused by the lack of focus on the main subject.</td>', 'Interesting idea. My eye is confused by the lack of focus on the main subject.', '2007-03-09 11:27:01.000000', NULL, 1),
(3446118, 480282, 58610, '<td valign="top">Closer, please. Closer. All that background gray really detracts from your wonderful subject.</td>', 'Closer, please. Closer. All that background gray really detracts from your wonderful subject.', '2007-03-09 11:28:34.000000', NULL, 1),
(3446129, 480108, 41116, '<td valign="top">I like how you got the reflection off the stones. Nice composition also. - 7</td>', 'I like how you got the reflection off the stones. Nice composition also. - 7', '2007-03-09 11:30:37.000000', NULL, 1),
(3446131, 480263, 58610, '<td valign="top">Very primal and visceral. Makes me want to check my body for gaping wounds. Nice abstract with strong emotional impact.</td>', 'Very primal and visceral. Makes me want to check my body for gaping wounds. Nice abstract with strong emotional impact.', '2007-03-09 11:31:25.000000', NULL, 1),
(3446140, 480364, 41116, '<td valign="top">For my liking the shot would have worked better if both apples were in focus. The shadow in the left corner is also quite distracting. - 5</td>', 'For my liking the shot would have worked better if both apples were in focus. The shadow in the left corner is also quite distracting. - 5', '2007-03-09 11:33:20.000000', NULL, 1),
(3446143, 480490, 56250, '<td valign="top">My favorite shot of the challenge =)</td>', 'My favorite shot of the challenge =)', '2007-03-09 11:34:00.000000', NULL, 1),
(3446144, 480034, 68504, '<td valign="top">Very imaginative set up, effective lighting, dof, and composition.  If red were redder, horizontals strait, distracting shadow upper 2/3 left reduced (how?), this would be a 9 for me.</td>', 'Very imaginative set up, effective lighting, dof, and composition.  If red were redder, horizontals strait, distracting shadow upper 2/3 left reduced (how?), this would be a 9 for me.', '2007-03-09 11:34:13.000000', NULL, 1),
