(3446152, 480157, 58610, '<td valign="top">Is that you, Chele? I like the high key with red. Really works. Nicely cropped, too. Great shot.</td>', 'Is that you, Chele? I like the high key with red. Really works. Nicely cropped, too. Great shot.', '2007-03-09 11:37:26.000000', NULL, 1),
(3446159, 479025, 58610, '<td valign="top">Oversaturated and oversharped, but otherwise and really nice shot. Love the tree shadow matching with the emerging tree behind the  barn. NIcely seen and shot.</td>', 'Oversaturated and oversharped, but otherwise and really nice shot. Love the tree shadow matching with the emerging tree behind the  barn. NIcely seen and shot.', '2007-03-09 11:39:31.000000', NULL, 1),
(3446166, 479608, 58610, '<td valign="top">What a great concept and really well executed. I think you''ve got a little too much negative space at the top, but otherwise well composed.</td>', 'What a great concept and really well executed. I think you''ve got a little too much negative space at the top, but otherwise well composed.', '2007-03-09 11:42:07.000000', NULL, 1),
(3446171, 479900, 58610, '<td valign="top">An unusual vantage point. NIce abstract.</td>', 'An unusual vantage point. NIce abstract.', '2007-03-09 11:44:06.000000', NULL, 1),
