(3447891, 478202, 70000, '<td valign="top">Nice find. I think this could use a little more light or contrast but I really like the moment you captured here.</td>', 'Nice find. I think this could use a little more light or contrast but I really like the moment you captured here.', '2007-03-10 00:53:13.000000', NULL, 1),
(3447893, 480239, 70000, '<td valign="top">OMG KITTY!!! wow nice textures and composition. the red is a bit too overpoering though, could use a little less saturation I think so that the cat pops out a teeny bit more.</td>', 'OMG KITTY!!! wow nice textures and composition. the red is a bit too overpoering though, could use a little less saturation I think so that the cat pops out a teeny bit more.', '2007-03-10 00:54:14.000000', NULL, 1),
(3447894, 479890, 70000, '<td valign="top">How incredibly odd. I really like this for some reason though, it feels so otherworldly, nice</td>', 'How incredibly odd. I really like this for some reason though, it feels so otherworldly, nice', '2007-03-10 00:55:19.000000', NULL, 1),
(3447897, 479971, 70000, '<td valign="top">OMG i didn''t notice the surfer at first. This really puts the magnitue here into perspective nice. Wow really cool...I actually think that this could use a little less red though because it looks to forced. Just a little less saturation maybe? Wow I really like the composition here alot though.</td>', 'OMG i didn''t notice the surfer at first. This really puts the magnitue here into perspective nice. Wow really cool...I actually think that this could use a little less red though because it looks to forced. Just a little less saturation maybe? Wow I really like the composition here alot though.', '2007-03-10 00:56:39.000000', NULL, 1),
(3447898, 480528, 52130, '<td valign="top">owwwwwwwwwwww, this makes MY eye hurt! good find</td>', 'owwwwwwwwwwww, this makes MY eye hurt! good find', '2007-03-10 00:57:46.000000', NULL, 1),
(3447899, 477776, 70000, '<td valign="top">I really think this would be just as strong if not stronger without the crayons and stuff, it just makes it a bit too buisy and I think her red hair should be the focs here, also the left side has a shaddow in the backdrop. But I really like the lighting here.</td>', 'I really think this would be just as strong if not stronger without the crayons and stuff, it just makes it a bit too buisy and I think her red hair should be the focs here, also the left side has a shaddow in the backdrop. But I really like the lighting here.', '2007-03-10 00:57:47.000000', NULL, 1),
(3447915, 479172, 62318, '<td valign="top">This is one of those refreshing portraits. Simple, not typical, well exposed. It is a vote stopper, and as such highly rated.</td>', 'This is one of those refreshing portraits. Simple, not typical, well exposed. It is a vote stopper, and as such highly rated.', '2007-03-10 01:15:12.000000', NULL, 1),
(3447935, 478004, 61552, '<td valign="top">Good imagination!  Wow!</td>', 'Good imagination!  Wow!', '2007-03-10 01:33:13.000000', NULL, 1),
