(3447997, 480271, 11467, '<td valign="top">That is excellent for an indoor shot!!</td>', 'That is excellent for an indoor shot!!', '2007-03-10 02:46:34.000000', NULL, 1),
(3447998, 479145, 11467, '<td valign="top">That''s pretty close up.<br/>Needs to be more red for a red challenge though</td>', 'That''s pretty close up.Needs to be more red for a red challenge though', '2007-03-10 02:48:44.000000', NULL, 1),
