(3459240, 478831, 74156, '<td valign="top">Thank you so much for your votes.</td>', 'Thank you so much for your votes.', '2007-03-14 08:05:13.000000', NULL, 0),
(3459257, 478473, 56797, '<td valign="top">very creative shot. looks very tricky. i''d think the edges would break when trying to push the needle through. awesome job. Congrats!</td>', 'very creative shot. looks very tricky. i''d think the edges would break when trying to push the needle through. awesome job. Congrats!', '2007-03-14 08:13:26.000000', NULL, 0),
(3459265, 479116, 66597, '<td valign="top">I love this shot! One of the better in challenge, IMO. Great job of stretching yourself and taking a photo outside of your "usual" style. I never would have guessed this was yours. The color temperature looks perfect on this, BTW.</td>', 'I love this shot! One of the better in challenge, IMO. Great job of stretching yourself and taking a photo outside of your "usual" style. I never would have guessed this was yours. The color temperature looks perfect on this, BTW.', '2007-03-14 08:15:27.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3459268, 480273, 66597, '<td valign="top">Bob, this is an awesome shot! I gave you a good score, and think it should have finished much higher. I think the composition is really strong, and I love the dew drops on the cherries. Summer looks early in Michigan, LOL :-)</td>', 'Bob, this is an awesome shot! I gave you a good score, and think it should have finished much higher. I think the composition is really strong, and I love the dew drops on the cherries. Summer looks early in Michigan, LOL :-)', '2007-03-14 08:16:37.000000', NULL, 0),
(3459276, 477391, 66597, '<td valign="top">Huh? How could this not be over 6? One of the most creative of challenge, IMO. I gave you a high score, and think everyone else should have as well, dammit! :-) So creative and well done. I would encourage you to enter this one into a few "real" art contests.</td>', 'Huh? How could this not be over 6? One of the most creative of challenge, IMO. I gave you a high score, and think everyone else should have as well, dammit! :-) So creative and well done. I would encourage you to enter this one into a few "real" art contests.', '2007-03-14 08:18:17.000000', NULL, 0),
(3459282, 479912, 66597, '<td valign="top">Hiya, Jeffrey, I wondered how this was done! Very creative, looks totally real (I guess it is real, just in a "fake" setting!) Nice OOB entry for sure.</td>', 'Hiya, Jeffrey, I wondered how this was done! Very creative, looks totally real (I guess it is real, just in a "fake" setting!) Nice OOB entry for sure.', '2007-03-14 08:20:23.000000', NULL, 0),
(3459288, 480332, 66597, '<td valign="top">You got robbed on this. I thought it was most thought-provoking and an interesting entry indeed. Keep up the good work, and don''t let that score bother you.</td>', 'You got robbed on this. I thought it was most thought-provoking and an interesting entry indeed. Keep up the good work, and don''t let that score bother you.', '2007-03-14 08:21:39.000000', NULL, 0),
(3459296, 479912, 23484, '<td valign="top">Cool shot Jeffrey. You captured this well. It''s interesting what they go through to get what they want.</td>', 'Cool shot Jeffrey. You captured this well. It''s interesting what they go through to get what they want.', '2007-03-14 08:23:06.000000', NULL, 0),
(3459303, 480481, 23484, '<td valign="top">There is something about this that I really like but I just can''t put my finger on it. Maybe it''s the color and angle of the stubble. The thumbnail really pulls you into this shot.</td>', 'There is something about this that I really like but I just can''t put my finger on it. Maybe it''s the color and angle of the stubble. The thumbnail really pulls you into this shot.', '2007-03-14 08:25:25.000000', NULL, 0),
(3459311, 480332, 23484, '<td valign="top">God I love the Moody Blues! This is a nice shot but I would like to see it a bit lighter. Not completely, just a little.  Nice shot.</td>', 'God I love the Moody Blues! This is a nice shot but I would like to see it a bit lighter. Not completely, just a little.  Nice shot.', '2007-03-14 08:27:03.000000', NULL, 0),
(3459312, 479436, 60614, '<td valign="top">Congratulations on your top 30 finish.  This really is an awsome picture.  But I am biased since my favorite color is red.</td>', 'Congratulations on your top 30 finish.  This really is an awsome picture.  But I am biased since my favorite color is red.', '2007-03-14 08:27:07.000000', NULL, 0),
(3459325, 479736, 23484, '<td valign="top">This is a nice shot. I think what hurt was that it''s a bit congested but it wouldn''t look as good without some brush in there. I like the fact that the barn is not over saturated.  Nice job.</td>', 'This is a nice shot. I think what hurt was that it''s a bit congested but it wouldn''t look as good without some brush in there. I like the fact that the barn is not over saturated.  Nice job.', '2007-03-14 08:30:01.000000', NULL, 0),
